#   source   krateo-blueprints/openstack-ironic-operator-kog  hack/capture-watch-stream.py
#   ref      main (fetched 2026-11-28; NOT the PR branch)
#   commit   f45b455b974e9e2842c5d109ec9562c60ac05ddd  (last upstream commit touching this file)
