"""Record a `kubectl get --watch` stream as timestamped JSONL.  Reads stdin, writes stdout.

    kubectl get RESOURCE.VERSION.GROUP --field-selector metadata.name=NAME \\
        --watch --output-watch-events -o json | hack/capture-watch-stream.py > capture.jsonl
    hack/capture-watch-stream.py --summary capture.jsonl

WHAT IT IS FOR. `-o json` watch events arrive as concatenated pretty-printed objects with no
per-event time. A peer asked for the stream itself rather than a summary of it, so this
emits one JSONL record per event: the reader's own timestamps plus the UNMODIFIED object.

WHAT IT DOES NOT DO. It never starts kubectl, never talks to a cluster, never mutates
anything: it reads stdin and writes stdout (the self-test proves that from the source).
It also does not judge. hack/watch-condition-flap.py renders verdicts; this records, so a
conclusion drawn from a capture is drawn by the reader, from the whole file.

WHY EACH PART EXISTS. Every one comes from a defect found in a real record.

  1. Two time bases, labelled IN THE FILE. `delivered_wall`/`delivered_t` are when THIS
     process printed the event; any timestamp inside `event` (annotations, a condition's
     lastTransitionTime) is when the apiserver STORED it. In one record they differed by
     94.7s, and reading the delivery column as a timeline turned a one-second annotation
     span into an apparent 94-second one -- the opposite conclusion, with no arithmetic
     error anywhere. The fields are therefore not called `t`/`wall`, and the first line
     is a header that says so, because a reader a week later has only the file.

  2. Probable re-list. After a 410 Gone, kubectl re-lists and replays ADDED for objects
     that already exist, so a gap in the RECORD becomes indistinguishable from a gap in
     the WRITES. A second ADDED for a uid already seen is the observable, and needs no
     cooperation from kubectl. It is flagged per line and counted in the summary.

  3. An exit cause, always. One run delivered three of a tick's four events and stopped,
     and nothing said so: the file simply ended, which reads as "nothing more happened".
     So every exit path writes a final summary record (counts, clean EOF vs failed read
     vs signal, the window, bytes of a truncated trailing object left unparsed). SIGINT
     and SIGTERM are handled for that reason. A closed stdout cannot carry a summary; it
     is the one path that exits quietly, and it exits with a code that says so.

  4. `--summary FILE`. Three peers asked for the same projection and it was hand-written
     three times; the projection belongs to the script, not to each reader.

Reads use os.read, not sys.stdin.read(4096): on a pipe the latter waits for 4096 bytes or
EOF, which would deliver a lone event only when the NEXT one arrived and corrupt exactly
the delivery times this tool exists to record.

EXIT CODES. 0 clean capture (stdin reached EOF, nothing left unparsed); 2 the capture is
INCOMPLETE (signal, failed read, truncated trailing object, closed stdout) or --summary's
file is unreadable; 64 usage error, kept distinct so a typo is never mistaken for a result.

`--self-test` runs offline: in-memory feeds plus real child processes of this script. No
cluster is touched.
"""
import argparse
import ast
import codecs
import datetime
import io
import json
import os
import signal
import sys
import time

SCHEMA = 1
EXIT_CLEAN, EXIT_INCOMPLETE, EXIT_USAGE = 0, 2, 64
ANNOTATION_NEEDLE = "external-create"

HEADER_NOTE = (
    "TWO TIME BASES. `delivered_wall` and `delivered_t` on each event line are DELIVERY "
    "times from this reader's own clock: when this process printed the event. Any "
    "timestamp INSIDE `event` (metadata.annotations, status.conditions[].lastTransitionTime, "
    "metadata.creationTimestamp) is a WRITE time from the apiserver: when it stored the "
    "object. The two can differ by minutes; never read the delivery columns as a timeline "
    "of writes.")


def iso(epoch):
    return datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).isoformat(timespec="milliseconds")


def line(rec):
    return json.dumps(rec, separators=(",", ":")) + "\n"


# ---------------------------------------------------------------- capture
class Capture:
    """Turns arbitrary byte chunks into records. Pure: time comes from the injected clock."""

    def __init__(self, clock):
        self.clock = clock                  # () -> (wall epoch, monotonic seconds)
        self.start_wall, self.start_mono = clock()
        self.text = codecs.getincrementaldecoder("utf-8")(errors="replace")
        self.dec = json.JSONDecoder()
        self.buf = ""
        self.count = 0
        self.by_type = {}
        self.relists = 0
        self.added_uids = set()
        self.last_wall = self.start_wall
        self.last_mono = self.start_mono

    def header(self):
        return {"record": "header", "schema": SCHEMA, "reader_started_wall": iso(self.start_wall),
                "delivered_wall": "ISO-8601 UTC, this reader's clock, when the event line was printed",
                "delivered_t": "seconds since reader_started_wall, this reader's clock (monotonic)",
                "event": "the watch event exactly as kubectl printed it; times inside are apiserver write times",
                "note": HEADER_NOTE}

    def feed(self, chunk):
        """Return the event records completed by this chunk."""
        self.buf += self.text.decode(chunk)
        out = []
        while True:
            s = self.buf.lstrip()
            if not s:
                self.buf = ""
                break
            try:
                obj, end = self.dec.raw_decode(s)
            except json.JSONDecodeError:
                self.buf = s                # an object cut in half: wait for the rest
                break
            self.buf = s[end:]
            out.append(self._event(obj))
        return out

    def _event(self, raw):
        wall, mono = self.clock()
        self.last_wall, self.last_mono = wall, mono
        typ = raw.get("type") if isinstance(raw, dict) and isinstance(raw.get("type"), str) else None
        body = raw.get("object") if isinstance(raw, dict) and "object" in raw else raw
        meta = body.get("metadata") if isinstance(body, dict) else None
        uid = meta.get("uid") if isinstance(meta, dict) else None
        relist = False
        if typ == "ADDED" and isinstance(uid, str):
            relist = uid in self.added_uids
            self.added_uids.add(uid)
        self.count += 1
        self.relists += 1 if relist else 0
        key = typ if typ is not None else "(no type)"
        self.by_type[key] = self.by_type.get(key, 0) + 1
        return {"record": "event", "seq": self.count, "delivered_wall": iso(wall),
                "delivered_t": round(mono - self.start_mono, 3), "probable_relist": relist, "event": raw}

    def leftover_bytes(self):
        pending = self.text.getstate()[0]   # bytes of a split multi-byte character
        return len(self.buf.strip().encode("utf-8")) + len(pending)

    def summary(self, cause, stdin_eof):
        wall, mono = self.clock()
        left = self.leftover_bytes()
        return {"record": "summary", "exit_cause": cause, "stdin_clean_eof": stdin_eof,
                "events": self.count, "by_type": self.by_type, "probable_relists": self.relists,
                "leftover_bytes": left,
                "leftover_note": ("the stream ended inside an object; these bytes were NOT decoded" if left else None),
                "window_s": round(mono - self.start_mono, 3),
                "first_delivered_wall": iso(self.start_wall), "last_delivered_wall": iso(self.last_wall),
                "closed_wall": iso(wall)}


class Guard:
    """Lets a signal handler interrupt the blocking read without tearing a write in half."""

    def __init__(self):
        self.in_read = False
        self.pending = None


class Interrupted(Exception):
    pass


def default_clock():
    return time.time(), time.monotonic()


def capture(read_chunk, out, clock=default_clock, guard=None):
    """Drive a Capture to the end of input. Returns an exit code; always tries to write a summary."""
    guard = guard or Guard()
    cap = Capture(clock)
    cause, eof = None, False
    try:
        out.write(line(cap.header()))
        out.flush()
        while cause is None:
            try:
                guard.in_read = True
                if guard.pending:
                    raise Interrupted(guard.pending)
                chunk = read_chunk()
            except Interrupted as e:
                cause = str(e)
                break
            except OSError as e:
                cause = "read_error: %s" % e
                break
            finally:
                guard.in_read = False
            if not chunk:
                cause, eof = "eof", True
                break
            for rec in cap.feed(chunk):
                out.write(line(rec))
            out.flush()
            if guard.pending:
                cause = guard.pending
        if cause is None:
            cause = guard.pending
        out.write(line(cap.summary(cause, eof)))
        out.flush()
    except BrokenPipeError:
        return EXIT_INCOMPLETE
    return EXIT_CLEAN if cause == "eof" and cap.leftover_bytes() == 0 else EXIT_INCOMPLETE


def run_capture():
    guard = Guard()

    def on_signal(signum, _frame):
        name = signal.Signals(signum).name
        guard.pending = name
        if guard.in_read:
            raise Interrupted(name)

    signal.signal(signal.SIGINT, on_signal)
    signal.signal(signal.SIGTERM, on_signal)
    fd = sys.stdin.fileno()
    try:
        code = capture(lambda: os.read(fd, 65536), sys.stdout, guard=guard)
    except BrokenPipeError:
        code = EXIT_INCOMPLETE
    # Python flushes stdout again at shutdown; on a closed pipe that prints a traceback.
    try:
        sys.stdout.flush()
    except (BrokenPipeError, ValueError):
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    return code


# ---------------------------------------------------------------- --summary
def conditions_of(obj):
    c = ((obj.get("status") or {}).get("conditions")) if isinstance(obj, dict) else None
    return [x for x in c if isinstance(x, dict)] if isinstance(c, list) else []


def render_summary(lines_in):
    """JSONL lines -> (text, ok). A projection of what was recorded; no verdict."""
    out = ["TIME BASES",
           "  delivered_wall / delivered_t : DELIVERY time, this reader's clock, when the line was printed",
           "  lastTransitionTime / annotations : WRITE time, the apiserver's clock, when it stored the object",
           "  These can differ by minutes. Compare writes with writes, never with the delivery column.",
           ""]
    out.append("%-4s %-12s %-9s %-14s %-4s %s" % ("SEQ", "delivered_t", "TYPE", "resourceVersion", "gen", ""))
    saw_header = saw_summary = False
    ok = True
    for n, raw in enumerate(lines_in, 1):
        if not raw.strip():
            continue
        try:
            rec = json.loads(raw)
        except ValueError as e:
            out.append("line %d: not JSON (%s)" % (n, e))
            ok = False
            continue
        kind = rec.get("record") if isinstance(rec, dict) else None
        if kind == "header":
            saw_header = True
        elif kind == "event":
            ev = rec.get("event")
            body = ev.get("object") if isinstance(ev, dict) and isinstance(ev.get("object"), dict) else ev
            meta = (body.get("metadata") if isinstance(body, dict) else None) or {}
            typ = ev.get("type") if isinstance(ev, dict) else None
            out.append("%-4s %-12s %-9s %-14s %-4s %s" % (
                rec.get("seq", "?"), rec.get("delivered_t", "?"), typ or "-", meta.get("resourceVersion", "-"),
                meta.get("generation", "-"), "PROBABLE RE-LIST" if rec.get("probable_relist") else ""))
            for k, v in sorted((meta.get("annotations") or {}).items()):
                if ANNOTATION_NEEDLE in k:
                    out.append("       annotation %s = %s   [write time, inside object]" % (k, v))
            for c in conditions_of(body):
                out.append("       condition %s=%s/%s  lastTransitionTime=%s   [write time]" % (
                    c.get("type"), c.get("status"), c.get("reason"), c.get("lastTransitionTime")))
        elif kind == "summary":
            saw_summary = True
            out.append("")
            out.append("SUMMARY RECORD: exit_cause=%s stdin_clean_eof=%s events=%s by_type=%s probable_relists=%s "
                       "leftover_bytes=%s window_s=%s" % (
                           rec.get("exit_cause"), rec.get("stdin_clean_eof"), rec.get("events"),
                           json.dumps(rec.get("by_type")), rec.get("probable_relists"),
                           rec.get("leftover_bytes"), rec.get("window_s")))
        else:
            out.append("line %d: unrecognised record %r" % (n, kind))
            ok = False
    if not saw_header:
        out.append("NOTE: no header record; the time-base labels above are this tool's, not the file's")
    if not saw_summary:
        out.append("NOTE: no summary record; the capture ended without one (process killed, or not written by this tool)")
    return "\n".join(out) + "\n", ok


# ---------------------------------------------------------------- self-test
BANNED_IMPORTS = {"subprocess", "socket", "ssl", "http", "urllib", "requests"}
BANNED_CALLS = {"system", "popen", "Popen", "run", "call", "check_call", "check_output",
                "execv", "execvp", "execl", "execlp", "spawnv", "spawnl", "posix_spawn", "fork"}
MUTATING_VERBS = set("create apply patch delete replace edit scale annotate label".split())
EXEMPT_PREFIX = ("self_test", "_st_")


def scan_source(src):
    """What the NON-test code of a module could reach: imports, process-spawning calls, kubectl-shaped argv."""
    tree = ast.parse(src)
    hits = []

    def visit(node):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith(EXEMPT_PREFIX):
            return
        if isinstance(node, ast.Import):
            hits.extend("import " + a.name for a in node.names if a.name.split(".")[0] in BANNED_IMPORTS)
        elif isinstance(node, ast.ImportFrom) and (node.module or "").split(".")[0] in BANNED_IMPORTS:
            hits.append("from " + node.module)
        elif isinstance(node, ast.Call):
            f = node.func
            name = f.attr if isinstance(f, ast.Attribute) else getattr(f, "id", None)
            if name in BANNED_CALLS:
                hits.append("call " + name)
        elif isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            # Only argv-shaped literals: a bare string such as errors="replace" is not a command.
            for el in node.elts:
                if isinstance(el, ast.Constant) and isinstance(el.value, str) \
                        and (el.value.strip() == "kubectl" or el.value.strip() in MUTATING_VERBS):
                    hits.append("string %r" % el.value.strip())
        for child in ast.iter_child_nodes(node):
            visit(child)

    for top in tree.body:
        if isinstance(top, ast.Expr) and isinstance(top.value, ast.Constant):
            continue                            # the module docstring may talk about kubectl
        visit(top)
    return hits


def _doc(uid="u1", rv="1", typ="ADDED", gen=1, ann=None, conds=None):
    obj = {"kind": "K", "metadata": {"uid": uid, "resourceVersion": rv, "generation": gen}}
    if ann:
        obj["metadata"]["annotations"] = ann
    if conds:
        obj["status"] = {"conditions": conds}
    return {"type": typ, "object": obj}


def _pretty(*docs):
    return "".join(json.dumps(d, indent=2) + "\n" for d in docs).encode()


class _Clock:
    def __init__(self):
        self.t = 0.0

    def __call__(self):
        self.t += 1.0
        return 1_700_000_000.0 + self.t, self.t


def _st_child(args, stdin=None):
    import subprocess
    return subprocess.Popen([sys.executable, "-I", os.path.abspath(__file__)] + args,
                            stdin=subprocess.PIPE if stdin is not None else None,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE)


def _st_tail(text):
    """Last JSONL record of a capture, {} if there is none: a missing summary must FAIL a check, not crash it."""
    rows = text.splitlines()
    return json.loads(rows[-1]) if rows else {}


def _st_read_line(p, timeout):
    import threading
    box = []
    t = threading.Thread(target=lambda: box.append(p.stdout.readline()), daemon=True)
    t.start()
    t.join(timeout)
    return box[0] if box else None


def self_test():
    import subprocess
    import tempfile
    passed = total = 0

    def check(label, ok):
        nonlocal passed, total
        total += 1
        passed += 1 if ok else 0
        print("  %s %s" % ("ok  " if ok else "FAIL", label))

    print("SELF-TEST")
    a, b = _doc("u1", "1"), _doc("u1", "2", "MODIFIED")
    blob = _pretty(a, b)

    # -- decoding: concatenated pretty-printed objects, unmodified
    cap = Capture(_Clock())
    recs = cap.feed(blob)
    check("two concatenated pretty-printed events are both decoded", len(recs) == 2)
    check("the event object is passed through unmodified", [r["event"] for r in recs] == [a, b])
    check("seq numbers the events 1,2", [r["seq"] for r in recs] == [1, 2])

    # -- a chunk boundary anywhere, including mid-token and mid-UTF-8 character
    uni = _pretty(_doc("u1", "1", ann={"note": "café ✓"}), b)
    whole = [r["event"] for r in Capture(_Clock()).feed(uni)]
    splits_ok = True
    for cut in range(1, len(uni)):
        c = Capture(_Clock())
        got = [r["event"] for r in c.feed(uni[:cut])] + [r["event"] for r in c.feed(uni[cut:])]
        splits_ok = splits_ok and got == whole and c.leftover_bytes() == 0
    check("splitting the stream at every byte offset yields the same events (incl. a multi-byte character)",
          splits_ok and len(whole) == 2)
    half = Capture(_Clock())
    check("control: half an object emits nothing yet", half.feed(blob[:20]) == [] and half.leftover_bytes() > 0)

    # -- truncated trailing object is reported, not dropped
    cut = blob[:len(blob) - 15]
    c = Capture(_Clock())
    c.feed(cut)
    s = c.summary("eof", True)
    check("a truncated trailing object is reported as leftover_bytes > 0 in the summary",
          s["events"] == 1 and s["leftover_bytes"] > 0 and s["leftover_note"])
    c = Capture(_Clock())
    c.feed(blob)
    check("control: a complete stream has leftover_bytes == 0", c.summary("eof", True)["leftover_bytes"] == 0)
    sink = io.StringIO()
    code = capture(iter([cut, b""]).__next__, sink, _Clock())
    check("a truncated stream exits INCOMPLETE even though stdin reached EOF",
          code == EXIT_INCOMPLETE and _st_tail(sink.getvalue()).get("stdin_clean_eof") is True)

    # -- probable re-list
    c = Capture(_Clock())
    r = c.feed(_pretty(_doc("u1", "1"), _doc("u1", "2", "MODIFIED"), _doc("u1", "3", "ADDED")))
    check("a second ADDED for a uid already seen is flagged probable_relist",
          [x["probable_relist"] for x in r] == [False, False, True])
    check("the summary counts probable re-lists", c.summary("eof", True)["probable_relists"] == 1)
    c = Capture(_Clock())
    r = c.feed(_pretty(_doc("u1", "1"), _doc("u2", "2")))
    check("control: an ADDED for a DISTINCT uid is not flagged",
          [x["probable_relist"] for x in r] == [False, False] and c.summary("eof", True)["probable_relists"] == 0)
    c = Capture(_Clock())
    r = c.feed(_pretty(_doc("u1", "1", "MODIFIED"), _doc("u1", "2", "MODIFIED")))
    check("control: repeated MODIFIED for one uid is not a re-list", not any(x["probable_relist"] for x in r))
    c = Capture(_Clock())
    c.feed(_pretty(_doc("u1", "1"), _doc("u1", "2", "MODIFIED"), _doc("u1", "3", "MODIFIED")))
    check("per-type counts are kept", c.summary("eof", True)["by_type"] == {"ADDED": 1, "MODIFIED": 2})

    # -- header and time-base labels
    h = Capture(_Clock()).header()
    check("the header record names both time bases", all(w in h["note"] for w in ("DELIVERY", "WRITE", "apiserver")))
    check("the header names the delivered_* fields", "delivered_wall" in h and "delivered_t" in h)
    ev = Capture(_Clock()).feed(_pretty(a))[0]
    check("event lines carry delivered_wall/delivered_t and NOT bare `t`/`wall`",
          "delivered_wall" in ev and "delivered_t" in ev and "t" not in ev and "wall" not in ev)
    sink = io.StringIO()
    capture(iter([blob, b""]).__next__, sink, _Clock())
    recs = [json.loads(x) for x in sink.getvalue().splitlines()]
    check("the first line is the header and the last is the summary",
          recs[0].get("record") == "header" and recs[-1].get("record") == "summary" and len(recs) == 4)

    # -- exit causes in-process
    check("clean EOF: cause eof, stdin_clean_eof true, exit 0",
          recs[-1].get("exit_cause") == "eof" and recs[-1].get("stdin_clean_eof") is True)

    def failing():
        raise OSError(5, "Input/output error")
    sink = io.StringIO()
    code = capture(failing, sink, _Clock())
    last = _st_tail(sink.getvalue())
    check("a failed read still writes a summary naming read_error, with stdin_clean_eof false",
          str(last.get("exit_cause")).startswith("read_error") and last.get("stdin_clean_eof") is False
          and code == EXIT_INCOMPLETE)

    # -- real child processes
    p = _st_child([], stdin=True)
    out, err = p.communicate(timeout=20)   # closes stdin itself; a pre-close breaks py3.9
    rows = [json.loads(x) for x in out.decode().splitlines()]
    check("child, empty stdin: summary present on clean EOF and exit 0",
          p.returncode == EXIT_CLEAN and rows[-1].get("record") == "summary" and rows[-1].get("exit_cause") == "eof")

    p = _st_child([], stdin=True)
    _st_read_line(p, 20)                                    # header
    p.stdin.write(_pretty(a))
    p.stdin.flush()
    got = _st_read_line(p, 10)                              # stdin stays open: only an immediate read delivers it
    check("a lone event is delivered immediately, not held until 4096 bytes or EOF",
          got is not None and json.loads(got).get("record") == "event")
    p.communicate(timeout=20)              # closes stdin itself; a pre-close breaks py3.9

    for sig in (signal.SIGTERM, signal.SIGINT):
        p = _st_child([], stdin=True)
        _st_read_line(p, 20)
        p.stdin.write(_pretty(a))
        p.stdin.flush()
        _st_read_line(p, 10)
        p.send_signal(sig)
        rest, err = p.communicate(timeout=20)
        tail = [json.loads(x) for x in rest.decode().splitlines()]
        check("after %s the summary is still written, naming the signal, exit %d" % (sig.name, EXIT_INCOMPLETE),
              bool(tail) and tail[-1].get("record") == "summary" and tail[-1].get("exit_cause") == sig.name
              and tail[-1].get("events") == 1 and p.returncode == EXIT_INCOMPLETE)

    p = _st_child([], stdin=True)
    _st_read_line(p, 20)
    p.stdout.close()                                        # the downstream reader goes away
    try:
        p.stdin.write(_pretty(a, b))
        p.stdin.flush()
    except BrokenPipeError:
        pass
    _, err = p.communicate(timeout=20)     # closes stdin itself; a pre-close breaks py3.9
    check("a closed stdout does not traceback and exits INCOMPLETE",
          b"Traceback" not in err and b"BrokenPipe" not in err and p.returncode == EXIT_INCOMPLETE)

    # -- --summary
    with tempfile.TemporaryDirectory() as tmp:
        ann = {"krateo.io/external-create-attempted": "2026-11-28T10:00:01Z", "unrelated/note": "zzz"}
        conds = [{"type": "Ready", "status": "True", "reason": "Available", "lastTransitionTime": "2026-11-28T10:00:02Z"}]
        sink = io.StringIO()
        capture(iter([_pretty(_doc("u1", "41", ann=ann, gen=3, conds=conds), _doc("u1", "42", "ADDED")), b""]).__next__,
                sink, _Clock())
        path = os.path.join(tmp, "c.jsonl")
        with open(path, "w") as f:
            f.write(sink.getvalue())
        p = _st_child(["--summary", path])
        text = p.communicate(timeout=20)[0].decode()
        check("--summary labels BOTH time bases", "delivery" in text.lower() and "write time" in text.lower()
              and "delivered_t" in text and "lastTransitionTime" in text)
        check("--summary shows type, resourceVersion and generation", "ADDED" in text and "41" in text and " 3 " in text)
        check("--summary shows the external-create annotation, labelled as a write time on its own line",
              any("external-create-attempted = 2026-11-28T10:00:01Z" in l and "[write time" in l
                  for l in text.splitlines()))
        check("control: --summary does not show an annotation without external-create", "unrelated/note" not in text)
        check("--summary shows each condition as type=status/reason with its lastTransitionTime",
              any("Ready=True/Available  lastTransitionTime=2026-11-28T10:00:02Z" in l and "[write time" in l
                  for l in text.splitlines()))
        check("--summary marks the probable re-list and shows the summary record",
              "PROBABLE RE-LIST" in text and "SUMMARY RECORD: exit_cause=eof" in text and p.returncode == EXIT_CLEAN)
        nosum = "".join(sink.getvalue().splitlines(True)[:-1])
        t2, ok2 = render_summary(nosum.splitlines())
        check("a capture with no summary record says so", "no summary record" in t2 and ok2)
        t3, ok3 = render_summary(["{not json"])
        check("a malformed line is reported and makes --summary fail", "not JSON" in t3 and not ok3)
        p = _st_child(["--summary", os.path.join(tmp, "absent.jsonl")])
        p.communicate(timeout=20)
        check("--summary on a missing file exits INCOMPLETE, not 0", p.returncode == EXIT_INCOMPLETE)

    # -- usage errors are exit 64
    p = _st_child(["--no-such-flag"])
    p.communicate(timeout=20)
    check("an unknown flag exits 64", p.returncode == EXIT_USAGE)
    p = _st_child(["--summary"])
    p.communicate(timeout=20)
    check("a flag missing its argument exits 64", p.returncode == EXIT_USAGE)

    # -- read-only
    hits = scan_source(open(os.path.abspath(__file__)).read())
    check("the script's own code reaches no subprocess, socket, kubectl or mutating verb: %s" % (hits or "none"), not hits)
    bad = "import subprocess\nsubprocess.run(['kubectl', 'delete', 'x'])\ny = ('patch', 'x')\n"
    check("control: the scan flags an import, a spawn call, a kubectl argv and a mutating verb",
          {"import subprocess", "call run", "string 'kubectl'", "string 'patch'"} <= set(scan_source(bad)))

    print("SELF-TEST: %d/%d assertions passed" % (passed, total))
    return EXIT_CLEAN if passed == total else 1


# ---------------------------------------------------------------- CLI
class UsageParser(argparse.ArgumentParser):
    """Usage errors exit 64, so a typo is never mistaken for an incomplete capture (2)."""

    def error(self, message):
        self.print_usage(sys.stderr)
        sys.stderr.write("%s: error: %s\n" % (self.prog, message))
        sys.exit(EXIT_USAGE)


def main(argv=None):
    ap = UsageParser(
        allow_abbrev=False,
        description="Record `kubectl get --watch --output-watch-events -o json` from stdin as timestamped JSONL. "
                    "Read-only: never starts kubectl, never contacts a cluster.",
        epilog="Exit: 0 clean capture, 2 incomplete capture or unreadable --summary file, 64 usage error.")
    ap.add_argument("--summary", metavar="FILE", help="print a compact table of a captured JSONL file and exit")
    ap.add_argument("--self-test", "--selftest", action="store_true", dest="self_test",
                    help="run the offline self-test and exit")
    a = ap.parse_args(argv)
    if a.self_test:
        return self_test()
    if a.summary:
        try:
            with open(a.summary) as f:
                text, ok = render_summary(f.readlines())
        except OSError as e:
            sys.stderr.write("cannot read %s: %s\n" % (a.summary, e))
            return EXIT_INCOMPLETE
        sys.stdout.write(text)
        return EXIT_CLEAN if ok else EXIT_INCOMPLETE
    if sys.stdin.isatty():
        ap.error("stdin is a terminal; pipe `kubectl get ... --watch --output-watch-events -o json` into this")
    return run_capture()


if __name__ == "__main__":
    sys.exit(main())
